public static class IssuerMap
{
    private static readonly Dictionary<string, string> Prefix =
        new(StringComparer.OrdinalIgnoreCase)
        {
            ["https://lms.example"] = "lti-lms",
            ["https://auth.example"] = "oidc"
        };

    public static bool TryGetCode(string issuer, out string code) =>
        Prefix.TryGetValue(issuer, out code!);
}

public static class RegexCache
{
    public static Regex Email { get; }
    public static Regex Phone { get; }

    static RegexCache()
    {
        Email = new Regex(@"^[^@]+@[^@]+$", RegexOptions.Compiled);
        Phone = new Regex(@"^\d{10}$", RegexOptions.Compiled);
    }
}

